#!/usr/bin/env bash
cd "$(dirname "$0")/.." || exit 2   # the repo root, so this runs from any directory
# GENERATED by tools/gen-rosters.sh - edit that, then regenerate. A gate checks.
#
# The ARTIFACT roster for this repo: the checks that build the thing this repo
# exists to produce, from a clean state, and exercise it the way its consumer
# will. Ships with none registered, and with none registered it exits 2: an
# artifact that has never been exercised is a blind spot, not a pass.
#
# This is the slow tier. scripts/gates.sh answers "does the code still pass its
# own tests" on every push and must stay fast. This file answers "does the
# artifact still work" and runs on the SHIPPING event. There are two kinds:
#
#   Shipping is a push.   Vercel, Pages, any host that builds on push. Set
#                         SHIP_BRANCH below and COMMIT it. When that branch is
#                         pushed, the pre-push hook checks the pushed commit out
#                         into a scratch worktree and runs this file from inside
#                         it, so what is checked is exactly what ships. The
#                         worktree starts clean: install what the build needs.
#   Shipping is a command. A deploy CLI, a release script, an export. Leave
#                         SHIP_BRANCH empty and chain it by hand:
#                             bash scripts/ship.sh && <deploy command>
#                         The CLI deploys the working tree, so checking the
#                         working tree in place is the right thing here.
#
# USAGE
#   bash scripts/ship.sh           # run every check, then summarise
#   bash scripts/ship.sh --quiet   # silent on success; failures always speak
#
# EXIT STATUS - the same contract as gates.sh
#   0  every check passed.
#   1  at least one check FAILED. Do not ship.
#   2  a bare-name tool on a check's line is not on PATH, or nothing is
#      registered. A declared blind spot. Say so where the artifact is shipped.

# The branch whose push IS the shipping event. Empty = shipping is a command.
SHIP_BRANCH=""

set -uo pipefail

QUIET=0
[ "${1:-}" = "--quiet" ] && QUIET=1

PASS=0; FAIL=0; SKIP=0
FAILED_GATES=""; SKIPPED_GATES=""

say() { [ "$QUIET" = "1" ] || printf '%s\n' "$*"; }

# run_gate [--needs tool[,tool...]] <name> <command...>
#
# SKIP (exit 2 from the roster) happens in exactly one case: a tool named on
# this line by BARE NAME is not on PATH. That is <command> itself, plus
# anything declared with --needs. A bare name is the machine's; a PATH (anything
# containing a slash, like ./scripts/check.sh) is the repo's, and a missing one
# is a finding, never a skip. Nothing a gate does once it is running can turn
# a failure into a skip either: exit 2 from a found command is a finding, and
# so is exit 127, which is what `bash` returns when the SCRIPT it was handed is
# missing. A deleted or renamed check must block, not warn.
run_gate() {
  needs=""
  if [ "${1:-}" = "--needs" ]; then needs="$2"; shift 2; fi
  name="$1"; shift
  for t in $(printf '%s' "$needs" | tr ',' ' ') "$1"; do
    case "$t" in
      */*)
        if [ ! -e "$t" ]; then
          FAIL=$((FAIL+1)); FAILED_GATES="$FAILED_GATES $name"
          printf '  FAIL  %s (%s does not exist - deleted or renamed?)\n' "$name" "$t" >&2
          return
        fi ;;
      *)
        if ! command -v "$t" >/dev/null 2>&1; then
          SKIP=$((SKIP+1)); SKIPPED_GATES="$SKIPPED_GATES $name"
          printf '  SKIP  %s (%s is not on PATH)\n' "$name" "$t" >&2
          return
        fi ;;
    esac
  done
  out=$("$@" 2>&1); rc=$?
  if [ "$rc" = "0" ]; then
    PASS=$((PASS+1)); say "  ok    $name"
  else
    FAIL=$((FAIL+1)); FAILED_GATES="$FAILED_GATES $name"
    hint=""; [ "$rc" = "127" ] && hint=" - a file this gate runs is missing?"
    printf '  FAIL  %s (exit %s%s)\n' "$name" "$rc" "$hint" >&2
    [ -n "$out" ] && printf '%s\n' "$out" >&2
  fi
}

say "artifact checks:"
EMPTY_MSG="summary: no artifact checks registered. The artifact has never been exercised; that is a blind spot, not a pass. Name what this repo produces and register the steps that build and exercise it in scripts/ship.sh."

# ---------------------------------------------------------------------------
# REGISTER THE STEPS THAT BUILD AND EXERCISE THIS REPO'S ARTIFACT.
#
# Not the unit tests; those are gates.sh. Here: the artifact itself, produced
# from a clean state, then used the way its consumer uses it. A suite re-runs
# what was already green. This tier is the only one that reaches a defect the
# suite has no test for, which is the kind that ships.
#
# Examples:
#
#   run_gate "build"         npm run --silent build
#   run_gate "page renders"  bash scripts/render_check.sh      # open it; assert content; no console errors
#   run_gate --needs tleap "output runs" bash scripts/exec_generated.sh   # execute what the app generated
#   run_gate "export opens"  python3 scripts/check_export.py out/report.pdf
#
# A check whose tool this machine lacks declares it with --needs. That is the
# only way to say "could not run"; a check that exits 2 on its own has failed.
# Slow is allowed here; that is what this tier is for. Unreliable is not.
# ---------------------------------------------------------------------------
# --- checks begin ---
run_gate --needs uv "smoke table re-verifies" uv run --quiet python run_arms.py --verify results/amber_smoke.jsonl
# --- checks end ---

TOTAL=$((PASS+FAIL+SKIP))
if [ "$TOTAL" = "0" ]; then
  say "  (none registered)"
  printf '%s\n' "$EMPTY_MSG" >&2
  exit 2
fi

say "summary: $PASS passed, $FAIL failed, $SKIP could not run"

if [ "$FAIL" -gt 0 ]; then
  printf 'FAILED:%s\n' "$FAILED_GATES" >&2
  exit 1
fi
if [ "$SKIP" -gt 0 ]; then
  printf 'COULD NOT RUN:%s\n' "$SKIPPED_GATES" >&2
  exit 2
fi
exit 0
